'use strict';
function journeyStage(){return state.phase==='forest'?0:['plan','receipt'].includes(state.phase)?1:['logistics','logisticsReceipt'].includes(state.phase)?2:3;}
function renderJourneyNav(){const nav=document.getElementById('journeyNav');if(!state.journey){nav.innerHTML='';return;}const current=journeyStage(),done=state.phase==='result';nav.innerHTML=`<ol class="journey-nav" aria-label="Dein Weg vom Wald zum Vertragsabschluss">${[['Waldplanung','Auftrag & Vorbereitung'],['Holzernte','Vier Maschinenschichten'],['Logistik','Polter bis Werk'],['Abrechnung & Vertrag','Mengen prüfen & abschließen']].map(([name,sub],i)=>`<li class="${i<current||done?'complete':i===current?'current':''}" ${i===current?'aria-current="step"':''}><span class="journey-number">${i<current||done?'✓':i+1}</span><div><b>${name}</b><small>${sub}</small></div></li>`).join('')}</ol>`;}
function journeyHeading(title,text){return `<div class="intro journey-intro"><div><p class="eyebrow">CFHarvest · INTERFORST · ${journeyStage()+1} / 4</p><h1>${title}</h1><p>${text}</p></div><span class="journey-id">${state.journey.contract?.id||ForestJourney.contracts[state.journey.contractType].id}</span></div>`;}
function journeyChoice(key,label,options,hint){return `<label class="decision-field"><span>${label}</span><select data-journey="${key}" aria-label="${label}">${options.map(([value,title])=>`<option value="${value}" ${state.journey[key]===value?'selected':''}>${title}</option>`).join('')}</select><small>${hint}</small></label>`;}
function bindJourneyChoices(){app.querySelectorAll('[data-journey]').forEach(el=>el.onchange=()=>{state=ForestJourney.choose(state,el.dataset.journey,el.value);render();app.querySelector(`[data-journey="${el.dataset.journey}"]`)?.focus();});}
function nextJourney(next){state=next;render();window.scrollTo({top:0,behavior:'smooth'});}
function bindJourneyMap(){app.querySelectorAll('[data-handover],[data-bio]').forEach(el=>{const open=()=>openHandover(el.dataset.handover||el.dataset.bio);el.onclick=open;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();open();}};});app.querySelectorAll('[data-plot]').forEach(el=>{const select=()=>{state.harvester=state.forwarder=el.dataset.plot;render();};el.onclick=select;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select();}};});}
function contractCard(c){return `<section class="contract-card"><div class="contract-head"><div><p class="eyebrow">Liefervertrag · Spielauftrag</p><h2>${c.name}</h2></div><span>${c.id}</span></div><div class="contract-targets"><div><strong>${c.volume} <small>fm</small></strong><span>Mindest-Gesamtlieferung</span></div><div><strong>${c.saw} <small>fm</small></strong><span>davon Sägeholz</span></div></div><dl class="report-details"><div><dt>Lieferpunkt</dt><dd>Sägewerk / Industrieabnehmer, nach der Ernte im gebuchten Abfuhrfenster</dd></div><div><dt>Preis je fm, netto</dt><dd>${c.prices.saw} € Sägeholz · ${c.prices.pulp} € Industrieholz · ${c.prices.down} € abgewertetes Holz</dd></div><div><dt>Fehlmenge</dt><dd>${c.shortfallRate} €/fm vereinbarter Mengenausgleich im Spiel; Gesamt- und Sägeholzfehlmenge werden nicht doppelt belastet.</dd></div><div><dt>Abrechnungsbasis</dt><dd>Angeliefertes, dem Vertrag zugeordnetes Holz. Holz am Polter ist noch keine erfüllte Werkslieferung. Mehrmengen werden im Szenario zum gleichen Sortimentspreis abgenommen.</dd></div></dl></section>`;}
function renderForestPlanning(){const j=state.journey,c=ForestJourney.contracts[j.contractType],cost=120+(j.preparation==='field'?405:0);app.innerHTML=journeyHeading('Dein Auftrag beginnt im Wald.','Lege die Lieferzusage fest und entscheide, welche Informationen vor dem ersten Maschineneinsatz vorliegen.')+`<div class="journey-layout"><div>${contractCard(c)}${overviewMap()}</div><section class="journey-decisions"><div class="stage-card"><p class="eyebrow">01 · Waldplanung</p><h2>Was gibst du der Ernte mit?</h2>${journeyChoice('contractType','Welche Menge sagst du zu?',[['standard','Standard · 600 fm / 360 fm Sägeholz'],['premium','Mehrmenge · 720 fm / 460 fm Sägeholz']], 'Die höhere Zusage bringt 6 €/fm mehr für Sägeholz, aber höhere Folgekosten bei Fehlmengen.')}${journeyChoice('preparation','Vorbereitung im Revier',[['records','Aktenstand übernehmen · Lücken offen lassen'],['field','Vor Ort prüfen · Grenze und Erkundung']], 'Vor-Ort-Paket: Nordhang-Grenze klären und fehlende Teilfläche im Talgrund erkunden. 3 h Revierzeit vor den Ernteschichten + Anfahrt: 405 €. Beim Aktenstand bleiben diese Aufgaben für die Ernte offen.')}${journeyChoice('documentation','Arbeitsauftrag bereitstellen',[['paper','Papier und Telefon'],['digital','Strukturierter digitaler Auftrag']], 'Digital setzt aktuelle Schnittvorgaben und laufende Meldungen voraus. Das Maschinenteam muss die digitale Hiebsübergabe trotzdem bestätigen. Manuelle Übergabe bleibt möglich.')}</div><div class="stage-action"><b>${euro(cost)} Planungskosten</b><p>Deine Entscheidungen bestimmen die Ausgangslage für die folgenden vier Ernteschichten.</p><button class="primary" id="startHarvest">Vertrag übernehmen und Ernte planen</button></div><aside class="journey-tip"><b>Der rote Faden</b><p>Ein Auftrag, dieselben Hiebe und dieselben Mengen begleiten dich bis zur Abrechnung. Geerntet, gerückt, angeliefert und abgerechnet bleiben getrennte Zustände.</p></aside></section></div>`;bindJourneyChoices();bindJourneyMap();document.getElementById('startHarvest').onclick=()=>nextJourney(ForestJourney.start(state));}
function materialFlow(){const l=state.journey.logistics,r=state.journey.settlement;return `<div class="material-flow" aria-label="Mengen entlang der Prozesskette">${[['Waldlager',state.stands.reduce((a,x)=>a+x.stock,0),'geerntet, noch nicht gerückt'],['Am Polter',state.stands.reduce((a,x)=>a+x.roadside,0),'gerückt, noch nicht abgefahren'],['Angeliefert',l?.volume||0,'am Werk / Industrieabnehmer'],['Abrechenbar',r?Object.values(r.billable).reduce((a,x)=>a+x,0):0,'dem Vertrag zugeordnet']].map(([name,value,help])=>`<div><span>${name}</span><strong>${num(value)} <small>fm</small></strong><small>${help}</small></div>`).join('')}</div>`;}
function roadsideTable(){return `<div class="history-table-wrap"><table><thead><tr><th>Polter / Hieb</th><th>Sägeholz</th><th>Industrieholz</th><th>Abgewertet</th><th>Abfuhr</th></tr></thead><tbody>${state.stands.map(s=>`<tr><td>P-${s.id.toUpperCase()}01 · ${s.name}</td><td>${num(s.roadsideGrades.saw)} fm</td><td>${num(s.roadsideGrades.pulp)} fm</td><td>${num(s.roadsideGrades.down)} fm</td><td>${s.closed?'Gesperrt':s.roadside>.01?'Verfügbar':'Kein Bestand'}</td></tr>`).join('')}</tbody></table></div>`;}
function renderLogistics(){const p=ForestJourney.haulPreview(state);app.innerHTML=journeyHeading('Das Holz muss zum Kunden.','Plane Lkw mit dem tatsächlichen Polterbestand. Herkunft, Sortiment und Zufahrt entscheiden über eine erfolgreiche Lieferung.')+materialFlow()+`<div class="journey-layout"><div><section class="stage-card"><p class="eyebrow">03 · Polterübersicht</p><h2>${num(p.volume)} fm zur Abfuhr verfügbar</h2>${roadsideTable()}${p.blocked?`<p class="plan-error">${num(p.blocked)} fm liegen an gesperrten Hieben. Sie werden nicht verladen.</p>`:''}<p class="report-note">Nachbarholz gehört nicht zu diesen Liefermengen. Sägeholz und Industrieholz werden getrennt disponiert.</p></section><section class="stage-card"><h2>Speditionskapazität</h2><div class="fleet-mini"><div><span>L-01 / L-02 · Lkw-Pool</span><b>${p.booked} Touren gebucht</b><small>Maximal 30 Touren im gesamten Abfuhrfenster</small></div><div><span>Volumen je Tour im Spiel</span><b>bis 25 fm</b><small>Sortiment und Polter bleiben getrennt</small></div></div><p class="report-note">Vereinfachte Volumenkapazität. Reale Nutzlast, Holzfeuchte, Fahr- und Lenkzeiten werden hier nicht berechnet.</p></section></div><section class="journey-decisions"><div class="stage-card">${journeyChoice('haulMode','Wie viele Touren bestellst du?',[['matched','Nach tatsächlichem Polterbestand'],['estimate','Pauschal nach Vertragsmenge']], 'Bestandsorientiert: 85 € Disposition und passende Tourenzahl, maximal 30. Pauschal: Vertragsmenge / 25 fm, aufgerundet; auch leere Touren kosten 240 €. Teilladungen können zusätzliche Touren benötigen.')}${journeyChoice('access','Zufahrt und Lkw-Wendepunkte',[['checked','Vor der Abfuhr prüfen'],['unchecked','Ungeprüfte Zufahrt verwenden']], 'Prüfung: 120 €. Bei unpassender Zufahrt im Talgrund geht im Szenario eine Tour verloren; 180 € Umplanung kommen hinzu.')}${journeyChoice('deliveryDocs','Lieferscheine und Herkunft',[['linked','Mit Auftrag und Polter verknüpfen'],['paper','Papierliste weitergeben']], 'Digitale Zuordnung: 90 €. Im Papier-Szenario fehlt auf einem Beleg der Auftragsbezug; dieser kann später nachgeprüft werden.')}</div><div class="stage-action"><b>${euro(p.estimate)} geplante Logistikkosten</b><p>${p.needed} Touren für alle verfügbaren Sortiments- und Polterpartien benötigt; ${p.booked} gebucht.</p><button class="primary" id="runHaul">Abfuhr durchführen</button></div></section></div>`;bindJourneyChoices();document.getElementById('runHaul').onclick=()=>nextJourney(ForestJourney.haul(state));}
function ledger(items){return `<dl class="cost-ledger">${items.map(x=>`<div><dt>${x.label}</dt><dd>${euro(x.value)}</dd></div>`).join('')}</dl>`;}
function deliveryTable(){return `<div class="history-table-wrap"><table><thead><tr><th>Beleg / Lkw</th><th>Herkunft</th><th>Sortiment</th><th>Menge</th><th>Status</th></tr></thead><tbody>${state.journey.logistics.loads.map(x=>`<tr><td>${x.id} · ${x.truck}</td><td>${x.polter||x.site?.toUpperCase()||'—'}</td><td>${({saw:'Sägeholz',pulp:'Industrieholz',down:'Abgewertet'})[x.grade]||'—'}</td><td>${num(x.volume)} fm</td><td>${x.missingReference?'Auftragsbezug fehlt':x.status}</td></tr>`).join('')||'<tr><td colspan="5">Keine Tour disponiert.</td></tr>'}</tbody></table></div>`;}
function renderLogisticsReceipt(){const l=state.journey.logistics;app.innerHTML=journeyHeading('Die Lieferung ist dokumentiert.','Jetzt ist sichtbar, welche Mengen beim Kunden angekommen sind und welche noch im Wald liegen.')+materialFlow()+`<div class="report-columns"><section class="stage-card"><h2>${num(l.volume)} fm angeliefert</h2><div class="event-log">${l.logs.map(x=>`<article class="log-card ${x.kind}"><b>${x.title}</b><p>${x.text}</p></article>`).join('')}</div></section><section class="stage-card"><h2>${euro(l.cost)} Logistikkosten</h2>${ledger(l.costItems)}<p class="report-note">${l.empty} gebuchte Touren ohne Holz. ${num(l.remainingRoadside)} fm verbleiben am Polter.</p></section></div><details class="stage-card"><summary>Lieferscheine und einzelne Lkw-Touren ansehen</summary>${deliveryTable()}</details><div class="actions"><button class="primary" id="toSettlement">Mengen abrechnen und Vertrag abschließen</button></div>`;document.getElementById('toSettlement').onclick=()=>nextJourney(ForestJourney.toSettlement(state));}
function renderSettlement(){const j=state.journey,p=ForestJourney.settlementPreview(state),l=j.logistics;app.innerHTML=journeyHeading('Stimmt die letzte Zahl?','Gleiche Lieferscheine und Werkbelege ab. Schließe den Auftrag mit nachvollziehbaren Restaufgaben ab.')+`<div class="journey-layout"><div>${contractCard(j.contract)}<section class="stage-card"><p class="eyebrow">04 · Abrechnungsprüfung</p><h2>Eine Abweichung braucht eine Entscheidung.</h2><div class="reconcile-row"><span>Sägeholz laut Lieferscheinen</span><b>${num(l.delivered.saw)} fm</b></div><div class="reconcile-row"><span>Sägeholz laut vorläufigem Werkbeleg</span><b>${num(Math.max(0,l.delivered.saw-p.error))} fm</b></div><p>${p.error?`${num(p.error)} fm sind im Prüfszenario dem falschen Auftrag zugeordnet. Ein Belegabgleich kann die Zuordnung korrigieren.`:'Keine Sägeholzlieferung vorhanden; kein Zuordnungsfehler im Werkbeleg.'}</p>${l.loads.some(x=>x.missingReference)?'<p class="plan-error">Zusätzlich fehlt auf einem Papierlieferschein der Auftragsbezug.</p>':''}<p class="report-note">Dies ist ein Zuordnungsfall, kein automatischer Aufschlag bei echter Messdifferenz. Reale Abweichungen brauchen einen nachvollziehbaren Nachweis.</p></section><details class="stage-card"><summary>Lieferbelege ansehen</summary>${deliveryTable()}</details></div><section class="journey-decisions"><div class="stage-card">${journeyChoice('reconciliation','Mengen und Belege abgleichen',[['match','Lieferscheine und Werkbeleg prüfen'],['accept','Vorläufige Werkzuordnung übernehmen']], 'Mit verknüpften Daten: 80 €. Papierbelege nachrecherchieren: 180 €. Ohne Prüfung bleibt die strittige Zuordnung offen und wird vorerst nicht abgerechnet.')}${journeyChoice('closeout','Wie schließt du den Vertrag ab?',[['document','Restmengen und offene Aufgaben dokumentieren'],['force','Alles als vollständig erledigt melden']], 'Dokumentierter Abschluss: 120 €. Unbelegte Vollerledigung bei Restmengen oder offenen Vorfällen führt zu 350 € Nachbearbeitung.')}</div><div class="stage-action"><span>Voraussichtlich abrechenbar</span><b>${euro(p.invoice)}</b><p>${euro(p.openValue)} bis zur Belegklärung offen · ${euro(p.shortfallCost)} vereinbarter Mengenausgleich.</p><p><strong>${p.status}</strong></p><button class="primary" id="settleContract">Im Spiel abrechnen und abschließen</button><small>Simulation · keine reale Rechnung oder Vertragsänderung</small></div></section></div>`;bindJourneyChoices();document.getElementById('settleContract').onclick=()=>nextJourney(ForestJourney.settle(state));}
function renderJourneyResult(){const j=state.journey,r=j.settlement,l=j.logistics,score=ForestJourney.score(state),parts=ForestJourney.breakdown(state),opps=opportunities();app.innerHTML=journeyHeading('Vom Wald bis zum Abschluss.','So wirken deine Entscheidungen entlang der gesamten Prozesskette.')+`<section class="receipt final-score"><div class="summary"><div class="score"><strong>${score}</strong><span>von 1.000 Punkten</span></div><div><p class="eyebrow">${r.status}</p><h2>${euro(r.margin)} Wertbeitrag im Spiel</h2><p>${num(l.volume)} / ${j.contract.volume} fm angeliefert · ${num(l.delivered.saw)} / ${j.contract.saw} fm Sägeholz.</p><p>${euro(r.invoice)} abgerechnet · ${euro(r.openValue)} bis zur Klärung offen.</p>${previousResult?`<p class="previous-score">Vorherige Reise: ${previousResult.score} Punkte · jetzt ${score-previousResult.score>=0?'+':''}${score-previousResult.score} Punkte.</p>`:''}</div></div><div class="score-breakdown journey-score">${parts.map(p=>`<div><b>${p.name}</b><strong>${p.points}<small> / ${p.max}</small></strong><div class="meter"><i style="width:${p.points/p.max*100}%"></i></div><p>${p.detail}</p></div>`).join('')}</div></section>${materialFlow()}<div class="report-columns"><section class="stage-card"><h2>Auftrag ${j.contract.id} · Schlussübersicht</h2>${ledger([{label:'Abrechenbarer Holzwert',value:r.invoice},{label:'Erreichter Bereitstellungsbonus',value:r.bonus},{label:'Waldplanung',value:-j.plan.cost},{label:'Holzernte und Maschineneinsatz',value:-state.history.reduce((a,x)=>a+x.cost,0)},{label:'Lkw-Logistik',value:-l.cost},{label:'Abrechnung und Mengenausgleich',value:-r.cost},{label:'Wertbeitrag',value:r.margin}])}<p class="report-note">Keine doppelte Erlösbuchung: Der frühere Polterwert war vorläufig. Jetzt zählt der abrechenbare Lieferwert. Holzeinkauf, Kulturkosten, Gemeinkosten und Steuern sind nicht enthalten.</p></section><section class="stage-card"><h2>Was bleibt zu übergeben?</h2><ul class="closeout-list"><li>${num(r.shortfall)} fm Vertragsfehlmenge · ${euro(r.shortfallCost)} Mengenausgleich</li><li>${num(state.stands.reduce((a,x)=>a+x.stock,0))} fm Waldlager und ${num(l.remainingRoadside)} fm Polterbestand</li><li>${state.closedSites.length} gesperrte Hiebe · ${num(state.neighbourVolume)} fm Nachbarholz gesondert</li><li>${r.matched?'Liefer- und Werkbelege abgeglichen.':r.issues.join(' ')||'Keine Belegabweichung festgestellt.'}</li><li>${r.status}</li></ul><p class="report-note">Ein dokumentierter Teilabschluss beseitigt keine Sperre und ersetzt keine Klärung eines Schadens. Restaufgaben gehen nachvollziehbar an den Auftraggeber.</p></section></div><section class="conversation"><p class="eyebrow">Gespräch am Messestand</p><h2>„Wo geht bei euch die Verbindung zwischen Hiebsauftrag, Polter, Lieferung und Abrechnung verloren?“</h2><p>${opps[0].question}</p></section><div class="cf-connections"><article><p class="eyebrow">Planung & Holzernte</p><h3>Gemeinsamer Auftrag, gemeinsame Informationen</h3><p>Das CFHarvest-Datenblatt beschreibt Arbeitsgebiete mit Vertragsinformationen, Produkten, Lieferungen, Karten und laufenden Produktionsmeldungen.</p></article><article><p class="eyebrow">Logistik & Abschluss</p><h3>Daten weitergeben, Mengen nachvollziehen</h3><p>Im Spiel nutzen die Folgeprozesse dieselbe Herkunft und dieselben Mengen. Lkw-Disposition, Rechnung und Vertragsabschluss sind ergänzende Spielszenarien; das verwendete Datenblatt weist sie nicht als eigenständige CFHarvest-Abrechnungsmodule aus.</p></article></div><details class="stage-card"><summary>Ernteschichten und Punktelogik ansehen</summary><div class="history-table-wrap"><table><thead><tr><th>Schicht</th><th>Geerntet</th><th>Gerückt</th><th>Abgewertet</th><th>Einsatzkosten</th></tr></thead><tbody>${state.history.map(x=>`<tr><td>${x.round}</td><td>${num(x.harvest)} fm</td><td>${num(x.forwarded)} fm</td><td>${num(x.downgraded)} fm</td><td>${euro(x.cost)}</td></tr>`).join('')}</tbody></table></div><p>Waldplanung 100, Holzernte 500, Logistik 200, Abrechnung und Vertrag 200 Punkte. Die Holzernte übernimmt die bisherige Bewertung mit halbem Gewicht; ihr Stand wird vor der Abfuhr festgehalten. Logistik bewertet Werkslieferung und Tourennutzung. Abrechnung bewertet abrechenbare Mengen, Prüfung und dokumentierten Abschluss.</p></details><div class="actions"><button class="primary" id="improve">Gesamte Reise mit besserer Planung wiederholen</button><button class="secondary" id="restart">Nächster Gast · neu beginnen</button></div><p class="source-note">Produktbezug: <a href="assets/CFHarvest-SpecSheet.pdf" target="_blank" rel="noopener">Trimble CFHarvest Datenblatt · 03/2026</a>. Sämtliche Preise, Verträge, Touren und Vorfälle sind Spielannahmen.</p>`;document.getElementById('improve').onclick=()=>{previousResult={score};nextJourney(ForestJourney.initial(true));};document.getElementById('restart').onclick=()=>{previousResult=null;nextJourney(ForestJourney.initial());};}
